// @autogenerated
// Lanza `ng <args>` inyectando la versión y la fecha de build (ver src/app/bootstrap/environment/environment.ts).
// Versión: APP_VERSION si está definida (CI); si no, la de package.json más el commit corto si hay git.
import { execSync, spawnSync } from 'node:child_process';
import { readFileSync } from 'node:fs';

const pkg = JSON.parse(readFileSync(new URL('../package.json', import.meta.url), 'utf8'));

function commit() {
  try {
    return execSync('git rev-parse --short HEAD', { stdio: ['ignore', 'pipe', 'ignore'] }).toString().trim();
  } catch {
    return '';
  }
}

const sha = commit();
const version = process.env.APP_VERSION || (sha ? `${pkg.version}+${sha}` : pkg.version);
const buildDate = new Date().toISOString();

const args = [
  ...process.argv.slice(2),
  '--define',
  `__APP_VERSION__=${JSON.stringify(version)}`,
  '--define',
  `__BUILD_DATE__=${JSON.stringify(buildDate)}`,
];
console.log(`Build ${version} (${buildDate})`);
const result = spawnSync('ng', args, { stdio: 'inherit', shell: process.platform === 'win32' });
process.exit(result.status ?? 1);
